// Simplified Raft node state machine — illustrative, not production
const FOLLOWER  = 'follower';
const CANDIDATE = 'candidate';
const LEADER    = 'leader';

class RaftNode {
  constructor(id, peers) {
    this.id          = id;
    this.peers       = peers;      // array of peer RPC handles
    this.state       = FOLLOWER;
    this.currentTerm = 0;
    this.votedFor    = null;       // candidateId we voted for this term
    this.log         = [];         // [{term, command}, ...]
    this.commitIndex = -1;         // highest committed entry index
    this.lastApplied = -1;         // highest applied entry index
    // Leader-only: track replication progress per follower
    this.nextIndex   = {};         // {peerId: nextIndexToSend}
    this.matchIndex  = {};         // {peerId: highestReplicatedIndex}
  }

  // --- ELECTION TIMEOUT (fires when no heartbeat received) ---
  onElectionTimeout() {
    this.state = CANDIDATE;
    this.currentTerm += 1;
    this.votedFor = this.id; // vote for self
    const term = this.currentTerm;
    const lastLog = this.log[this.log.length - 1] || { term: 0 };
    const lastLogIndex = this.log.length - 1;
    const lastLogTerm  = lastLog.term;
    const majority = Math.floor((this.peers.length + 1) / 2) + 1;
    let votes = 1; // self-vote

    const requests = this.peers.map(p =>
      p.requestVote({ term, candidateId: this.id, lastLogIndex, lastLogTerm })
        .catch(() => ({ voteGranted: false }))
    );

    Promise.all(requests).then(responses => {
      if (this.state !== CANDIDATE || this.currentTerm !== term) return;
      for (const r of responses) {
        if (r.term > this.currentTerm) { this.stepDown(r.term); return; }
        if (r.voteGranted) votes++;
      }
      if (votes >= majority) this.becomeLeader();
    });
  }

  // --- BECOME LEADER ---
  becomeLeader() {
    this.state = LEADER;
    // Optimistic next index: assume peers are fully caught up
    for (const p of this.peers) {
      this.nextIndex[p.id]  = this.log.length;
      this.matchIndex[p.id] = -1;
    }
    this.sendHeartbeats(); // establish authority immediately
    this.heartbeatTimer = setInterval(() => this.sendHeartbeats(), 50);
  }

  // --- APPEND ENTRIES (client write path) ---
  appendCommand(command) {
    if (this.state !== LEADER) throw new Error('Not leader — redirect to leader');
    this.log.push({ term: this.currentTerm, command });
    return this.replicateToFollowers();
  }

  replicateToFollowers() {
    return new Promise((resolve) => {
      const majority = Math.floor((this.peers.length + 1) / 2) + 1;
      let acks = 1; // leader counts itself
      const newIndex = this.log.length - 1;

      for (const peer of this.peers) {
        const prevIndex = this.nextIndex[peer.id] - 1;
        const entries   = this.log.slice(this.nextIndex[peer.id]);
        const prevTerm  = prevIndex >= 0 ? this.log[prevIndex].term : 0;

        peer.appendEntries({
          term: this.currentTerm,
          leaderId: this.id,
          prevLogIndex: prevIndex,
          prevLogTerm: prevTerm,
          entries,
          leaderCommit: this.commitIndex
        }).then(r => {
          if (r.success) {
            this.matchIndex[peer.id] = newIndex;
            this.nextIndex[peer.id]  = newIndex + 1;
            acks++;
            if (acks >= majority) {
              this.commitIndex = newIndex;
              resolve(this.applyToStateMachine(newIndex));
            }
          } else if (r.term > this.currentTerm) {
            this.stepDown(r.term);
          } else {
            // Follower log conflict — back up and retry
            this.nextIndex[peer.id] = Math.max(0, this.nextIndex[peer.id] - 1);
          }
        }).catch(() => { /* peer unreachable — retry on next heartbeat */ });
      }
    });
  }

  stepDown(newTerm) {
    this.state = FOLLOWER;
    this.currentTerm = newTerm;
    this.votedFor = null;
    clearInterval(this.heartbeatTimer);
  }

  applyToStateMachine(index) {
    // In a real system: pass to application state machine
    this.lastApplied = index;
    return this.log[index].command;
  }

  sendHeartbeats() {
    for (const peer of this.peers) {
      peer.appendEntries({
        term: this.currentTerm, leaderId: this.id,
        prevLogIndex: this.nextIndex[peer.id] - 1,
        prevLogTerm: 0, entries: [],
        leaderCommit: this.commitIndex
      }).catch(() => {});
    }
  }
}

// Classic Paxos — single-value consensus (illustrative)
// Models proposer and acceptor logic

class Acceptor {
  constructor() {
    this.promisedBallot = -1;  // highest ballot promised
    this.acceptedBallot = -1;  // ballot of last accepted proposal
    this.acceptedValue  = null;
  }

  // Phase 1: respond to Prepare(n)
  prepare(n) {
    if (n > this.promisedBallot) {
      this.promisedBallot = n;
      return {
        ok: true,
        acceptedBallot: this.acceptedBallot,
        acceptedValue:  this.acceptedValue
      };
    }
    return { ok: false }; // already promised higher ballot
  }

  // Phase 2: respond to Accept(n, v)
  accept(n, v) {
    if (n >= this.promisedBallot) {
      this.promisedBallot = n;
      this.acceptedBallot = n;
      this.acceptedValue  = v;
      return { ok: true };
    }
    return { ok: false }; // promised a higher ballot in the meantime
  }
}

class Proposer {
  constructor(id, acceptors) {
    this.id        = id;
    this.acceptors = acceptors;
    this.ballot    = id * 1000; // globally unique starting point
  }

  async propose(myValue) {
    this.ballot++;
    const n = this.ballot;
    const majority = Math.floor(this.acceptors.length / 2) + 1;

    // --- Phase 1: Prepare ---
    const promises = await Promise.all(
      this.acceptors.map(a => Promise.resolve(a.prepare(n)))
    );
    const granted = promises.filter(p => p.ok);
    if (granted.length < majority) throw new Error('Phase 1 failed — try higher ballot');

    // Adopt highest previously accepted value (Paxos safety rule)
    const alreadyAccepted = granted.filter(p => p.acceptedValue !== null);
    let valueToPropose = myValue;
    if (alreadyAccepted.length > 0) {
      // Must use the value with the highest accepted ballot
      const highest = alreadyAccepted.reduce((best, p) =>
        p.acceptedBallot > best.acceptedBallot ? p : best
      );
      valueToPropose = highest.acceptedValue;
      console.log(`Adopting prior value: ${valueToPropose} (ballot ${highest.acceptedBallot})`);
    }

    // --- Phase 2: Accept ---
    const accepts = await Promise.all(
      this.acceptors.map(a => Promise.resolve(a.accept(n, valueToPropose)))
    );
    const accepted = accepts.filter(a => a.ok);
    if (accepted.length < majority) throw new Error('Phase 2 failed — concurrent proposer?');

    console.log(`Consensus reached: value = ${valueToPropose}`);
    return valueToPropose;
  }
}

// Demo: two proposers competing
async function demo() {
  const acceptors = [new Acceptor(), new Acceptor(), new Acceptor()];
  const p1 = new Proposer(1, acceptors);
  const p2 = new Proposer(2, acceptors);

  // p1 runs Phase 1, then p2 runs a full round first
  acceptors[0].prepare(2001); // p2's ballot sneaks in
  acceptors[1].prepare(2001);

  // p1's Phase 2 will fail (acceptors promised higher ballot)
  // p2 can safely choose its value or adopt prior accepted value
  const result = await p2.propose('committed-value');
  console.log('Final:', result); // 'committed-value'
}
demo();
